// Prints every migration in supabase/migrations as one SQL script, in order and
// inside a single transaction, for setting up a new Supabase project from its
// SQL Editor without the Supabase CLI. Usage: npm run --silent db:bundle > setup.sql
import { readdirSync, readFileSync } from "node:fs";

const dir = new URL("../supabase/migrations/", import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

let sql =
  `-- The Bronx App: full database setup (${files.length} migrations).\n` +
  "-- Generated by scripts/bundle-migrations.mjs. Run once, on an empty Supabase project.\n" +
  "BEGIN;\n";
for (const file of files) sql += `\n-- ${file}\n${readFileSync(new URL(file, dir), "utf8").trim()}\n`;
sql += "\nCOMMIT;\n";

process.stdout.write(sql);
